'use strict';
const $=id=>document.getElementById(id),colors=['#177858','#2563b4','#c15c24','#8055ad','#b53e69','#548122','#268b94','#8d6227'];
let dataset=null,validation=null,enabled=new Set(),map=null,markers=null,page=0,visible=[],busy=false;
const leafletReady=!!window.L;
if(leafletReady){map=L.map('map',{preferCanvas:true}).setView([36.3,127.8],7);markers=L.layerGroup().addTo(map);
  if(/^https?:$/.test(location.protocol)){const tiles=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a> contributors'}).addTo(map);tiles.on('tileerror',()=>{$('map-note').textContent='배경지도를 불러오지 못했습니다. 인터넷 연결을 확인하세요. 좌표 목록과 지점 표시는 계속 사용할 수 있습니다.';});}
  else $('map-note').textContent='로컬 파일에서는 배경지도를 요청하지 않습니다. 배경지도를 보려면 게시된 웹사이트나 로컬 웹서버에서 실행하세요.';
}
function status(text,error=false){$('status').textContent=text;$('status').classList.toggle('error',error);}
function setBusy(value){busy=value;for(const id of ['files','encoding','demo','reset'])$(id).disabled=value;for(const id of ['latitude','longitude','label-column','show-map'])$(id).disabled=value||!dataset;}
function invalidate(){validation=null;markers?.clearLayers();enabled.clear();$('group-filters').replaceChildren();$('point-list').replaceChildren();for(const id of ['total-count','valid-count','invalid-count'])$(id).textContent='0';for(const id of ['select-all','select-none','download','fit','previous','next'])$(id).disabled=true;$('page-info').textContent='0 / 0';}
function loadDataset(data){
  if(!data||!Array.isArray(data.headers)||!Array.isArray(data.groups)||!data.groups.every(g=>g&&Array.isArray(g.rows)&&g.rows.every(Array.isArray)))throw Error('가져온 분리 결과 형식이 올바르지 않습니다.');
  invalidate();dataset=data;$('data-source').textContent=`${data.name||'분리 결과'} · ${data.groups.length}개 그룹 · ${data.groups.reduce((n,g)=>n+g.rows.length,0).toLocaleString()}행`;
  for(const id of ['latitude','longitude','label-column']){const select=$(id);select.replaceChildren(new Option(id==='label-column'?'행 번호':'열 선택',id==='label-column'?'-1':''));data.headers.forEach((h,i)=>select.add(new Option(`${h||'(제목 없음)'} · ${i+1}열`,String(i))));const guess=MapCore.guess(data.headers,id==='latitude'?'lat':id==='longitude'?'lon':'label');if(guess>=0)select.value=String(guess);}
  setBusy(false);status('위도·경도 열을 확인하고 지도에 표시를 누르세요.');
}
async function readFiles(files){if(busy)return;const selected=[...files];if(!selected.length)return;if(selected.some(f=>!/^.*\.(csv|xlsx)$/i.test(f.name))){status('CSV 또는 XLSX 파일만 선택하세요.',true);return;}setBusy(true);try{
  const tables=[];for(const file of selected){status(`${file.name} 읽는 중…`);await new Promise(resolve=>setTimeout(resolve,0));try{const bytes=await file.arrayBuffer();const book=/\.csv$/i.test(file.name)?XLSX.read(new TextDecoder($('encoding').value).decode(bytes),{type:'string',raw:true}):XLSX.read(bytes,{type:'array'});const sheet=book.Sheets[book.SheetNames[0]];const rows=sheet?XLSX.utils.sheet_to_json(sheet,{header:1,defval:'',raw:false,blankrows:false}):[];tables.push({file:file.name,sheet:book.SheetNames[0]||'',rows});}catch(e){throw Error(`${file.name}: ${e.message}`);}}
  const merged=MergeCore.mergeTables(tables,{header:true,source:true});if(merged.headers.length<=2)throw Error('파일에서 열 제목을 찾지 못했습니다.');
  const groups=new Map();for(const row of merged.rows){const key=row[merged.headers.length-2];if(!groups.has(key))groups.set(key,{value:key,rows:[]});groups.get(key).rows.push(row.slice(0,-2));}
  loadDataset({name:`선택한 파일 ${selected.length}개`,headers:merged.headers.slice(0,-2),groups:[...groups.values()]});
}catch(e){status(`파일을 가져오지 못했습니다. ${e.message}`,true);}finally{setBusy(false);}}
$('files').onchange=e=>{readFiles(e.target.files);e.target.value='';};$('drop').onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();if(!busy)$('files').click();}};
for(const type of ['dragenter','dragover'])$('drop').addEventListener(type,e=>{e.preventDefault();$('drop').classList.add('over');});for(const type of ['drop','dragleave'])$('drop').addEventListener(type,e=>{e.preventDefault();$('drop').classList.remove('over');});$('drop').addEventListener('drop',e=>readFiles(e.dataTransfer.files));window.addEventListener('drop',e=>e.preventDefault());window.addEventListener('dragover',e=>e.preventDefault());
for(const id of ['latitude','longitude','label-column'])$(id).onchange=()=>{invalidate();status('열 설정이 바뀌었습니다. 지도에 표시를 다시 누르세요.');};
function popup(record){const box=document.createElement('div'),title=document.createElement('strong');title.className='popup-title';title.textContent=record.label||'이름 없는 지점';box.append(title);const dl=document.createElement('dl');dl.className='popup-data';for(const [name,value] of [['그룹',record.group||'(빈 값)'],['그룹 내 행',record.rowIndex+1],...dataset.headers.map((h,i)=>[h||`열 ${i+1}`,record.row[i]??''])]){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=name;dd.textContent=String(value);dl.append(dt,dd);}box.append(dl);return box;}
function locate(record){if(!map)return;map.setView([record.lat,record.lon],Math.max(map.getZoom(),13));L.popup().setLatLng([record.lat,record.lon]).setContent(popup(record)).openOn(map);}
function fit(){if(map&&visible.length)map.fitBounds(visible.slice(0,5000).map(r=>[r.lat,r.lon]),{padding:[25,25],maxZoom:14});}
function renderList(){const source=validation?($('list-mode').value==='invalid'?validation.invalid:validation.points).filter(r=>enabled.has(r.groupIndex)):[];const pages=Math.ceil(source.length/50);page=Math.min(page,Math.max(pages-1,0));$('page-info').textContent=pages?`${page+1} / ${pages}`:'0 / 0';$('previous').disabled=!page;$('next').disabled=page>=pages-1;$('point-list').replaceChildren();const head=$('point-list').createTHead().insertRow();for(const title of ['지점 / 그룹','위도','경도',$('list-mode').value==='invalid'?'확인 사항':'위치']){const th=document.createElement('th');th.textContent=title;head.append(th);}const body=$('point-list').createTBody();for(const r of source.slice(page*50,page*50+50)){const tr=body.insertRow();[`${r.label||'(이름 없음)'} / ${r.group||'(빈 값)'}`,r.lat??'—',r.lon??'—'].forEach(v=>tr.insertCell().textContent=String(v));const last=tr.insertCell();if(r.reason)last.textContent=r.reason;else{const b=document.createElement('button');b.className='text-button';b.textContent='위치 보기';b.disabled=!map;b.onclick=()=>locate(r);last.append(b);}}}
function redraw(autoFit=true){if(!validation)return;visible=validation.points.filter(r=>enabled.has(r.groupIndex));const invalid=validation.invalid.filter(r=>enabled.has(r.groupIndex));markers?.clearLayers();visible.slice(0,5000).forEach(record=>{if(!map)return;L.circleMarker([record.lat,record.lon],{radius:7,color:colors[record.groupIndex%colors.length],fillOpacity:.8,weight:2}).bindPopup(()=>popup(record)).addTo(markers);});$('total-count').textContent=(visible.length+invalid.length).toLocaleString();$('valid-count').textContent=visible.length.toLocaleString();$('invalid-count').textContent=invalid.length.toLocaleString();$('fit').disabled=!map||!visible.length;$('download').disabled=!visible.length&&!invalid.length;renderList();if(autoFit)fit();status(`${enabled.size}개 그룹 · 유효 좌표 ${visible.length.toLocaleString()}개 · 좌표 확인 필요 ${invalid.length.toLocaleString()}행`+(visible.length>5000?' · 지도에는 처음 5,000개만 표시합니다.':'')+(!leafletReady?' · 지도 라이브러리를 불러오지 못했습니다. 좌표 목록은 사용할 수 있습니다.':''));}
$('show-map').onclick=()=>{if(!dataset||busy)return;try{invalidate();if($('latitude').value===''||$('longitude').value==='')throw Error('위도 열과 경도 열을 모두 선택하세요.');validation=MapCore.coordinates(dataset.headers,dataset.groups,Number($('latitude').value),Number($('longitude').value),Number($('label-column').value));dataset.groups.forEach((group,i)=>{enabled.add(i);const label=document.createElement('label');label.className='map-group';const check=document.createElement('input');check.type='checkbox';check.checked=true;check.onchange=()=>{check.checked?enabled.add(i):enabled.delete(i);page=0;redraw();};const span=document.createElement('span'),swatch=document.createElement('i');swatch.className='swatch';swatch.style.background=colors[i%colors.length];span.append(swatch,document.createTextNode(String(group.value||'(빈 값)')));const counts=document.createElement('small');counts.textContent=`유효 ${validation.points.filter(r=>r.groupIndex===i).length} · 확인 필요 ${validation.invalid.filter(r=>r.groupIndex===i).length}`;span.append(counts);label.append(check,span);$('group-filters').append(label);});$('select-all').disabled=$('select-none').disabled=false;page=0;redraw();}catch(e){status(e.message,true);}};
for(const [id,on] of [['select-all',true],['select-none',false]])$(id).onclick=()=>{if(!validation)return;enabled=new Set(on?dataset.groups.map((_,i)=>i):[]);document.querySelectorAll('.map-group input').forEach(el=>el.checked=on);page=0;redraw();};$('fit').onclick=fit;$('list-mode').onchange=()=>{page=0;renderList();};$('previous').onclick=()=>{page--;renderList();};$('next').onclick=()=>{page++;renderList();};
$('download').onclick=()=>{if(!validation)return;const entries=[...validation.points,...validation.invalid].filter(r=>enabled.has(r.groupIndex)).sort((a,b)=>a.groupIndex-b.groupIndex||a.rowIndex-b.rowIndex);const text=MergeCore.csvText({headers:['그룹','그룹 내 데이터 행',...dataset.headers,'검증 위도','검증 경도','좌표 검증'],rows:entries.map(r=>[r.group,r.rowIndex+1,...r.row,r.lat??'',r.lon??'',r.reason||'유효'])});const url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='위치_확인_결과.csv';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);};
$('demo').onclick=()=>{loadDataset({name:'예제 데이터 (기능 확인용)',headers:['지점명','위도','경도'],groups:[{value:'서울',rows:[['서울시청',37.5665,126.978],['서울역',37.5547,126.9706]]},{value:'부산',rows:[['부산역',35.1151,129.0414],['좌표 누락 예제','',129.04]]}]});$('show-map').click();};
$('reset').onclick=async()=>{setBusy(true);try{await MapBridge.clear();dataset=null;invalidate();for(const id of ['latitude','longitude','label-column'])$(id).replaceChildren(new Option('열 선택',''));history.replaceState(null,'',location.pathname);$('data-source').textContent='분리 페이지의 지도에서 확인으로 바로 가져올 수도 있습니다.';status('데이터와 브라우저의 임시 분리 결과를 지웠습니다.');}catch(e){status(e.message,true);}finally{setBusy(false);}};
(async()=>{const token=new URLSearchParams(location.search).get('split');if(!token)return;setBusy(true);try{const data=await MapBridge.get(token);if(!data)throw Error('분리 결과가 없거나 만료됐습니다. 분리 페이지에서 다시 가져오거나 파일을 직접 추가하세요.');loadDataset(data);}catch(e){status(e.message,true);}finally{setBusy(false);}})();
